"""stages.implement.hw: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from ... import prompts, state as state_mod
from ...flow import outcome
from ...prompts import SYSTEM_PROMPT
from ...runtime.llm import DEFAULT_MAX_TOOL_ROUNDS
from ...runtime import effects, commands, llm_step, observations, parsing, stage_services, tools
from ...runtime.hardware_tools import HardwareCodingToolset
from ...runtime.policy import PolicyError
from ...runtime.tools import DESIGN_SOURCE_FILES, RepoToolbox
from ...stages import fallbacks, feedback as feedback_mod
from ...stages.implement import delivery, intrinsics
from ...state import CfuDesignState


def _hardware_context(state: CfuDesignState, toolbox: RepoToolbox) -> dict:
    """Repo context whose hardware targets carry the live workspace content.

    The repair prompt must show the same bytes the edit is applied to. The
    snapshotted ``context`` captured at load_context holds the tracked scaffold,
    which stops matching once an earlier attempt has edited the overlay, so the
    run-workspace copy is substituted here.
    """
    context = dict(state.get("context", {}) or {})
    files = dict(context.get("files", {}) or {})
    run_root = state.get("run_root", "")
    overlays = tools.design_workspace_paths(run_root) if run_root else {}
    for tracked in DESIGN_SOURCE_FILES:
        overlay = overlays.get(tracked)
        if not overlay:
            continue
        try:
            text = toolbox.read_text(overlay, limit=1_000_000)
        except PolicyError:
            continue
        if text:
            files[tracked] = text
    context["files"] = files
    return context


def _hardware_evidence_paths(state: CfuDesignState) -> list[tuple[str, str]]:
    """Artifacts the hardware rung should read on demand, by path."""
    run_root = str(state.get("run_root", "") or "").rstrip("/")
    if not run_root:
        return []
    return stage_services.existing_evidence(state, [
        (f"{run_root}/07_analysis/workload_analysis.yaml", "workload analysis"),
        (f"{run_root}/08_isa/cfu_isa.yaml", "frozen ISA contract"),
        (f"{run_root}/09_implementation/hw_plan.md", "previous hardware plan (if any)"),
        (f"{run_root}/09_implementation/hw_changed_files.yaml", "previous hardware change record"),
        (f"{run_root}/workspace/design/", "this run's hardware overlay (your edit target lives here)"),
    ])


def implement_hw(state: CfuDesignState) -> CfuDesignState:
    """Hardware rung: design AgentCfu.scala / AgentCfuFiber.scala only."""
    toolbox = stage_services._toolbox_for_stage(state, "implementation")
    feedback = "\n\n".join(
        part
        for part in (
            feedback_mod.hardware_stuck_directive(state),
            feedback_mod.hardware_repair_feedback(state),
        )
        if part
    )
    if feedback:
        # The ledger is repair-context only: appending it to a clean prompt
        # would turn every re-run (e.g. an optimization round) into a "repair".
        ledger = feedback_mod.attempt_ledger_block(state.get("hw_attempts"))
        if ledger:
            feedback = f"{feedback}\n\n{ledger}"
    system = SYSTEM_PROMPT
    client = llm_step._llm(state)
    tools_enabled = llm_step._tools_enabled(state, client)
    failures = observations.failure_index(state)
    all_failures = failures.get("failures") or {}
    failure_ids = sorted(
        ident for ident, item in all_failures.items()
        if not isinstance(item, dict) or item.get("status", "current") == "current"
    )
    resolved_failure_ids = sorted(set(all_failures) - set(failure_ids))
    coding_enabled = bool(
        tools_enabled
        and not state.get("dry_run", False)
        and state.get("apply_patch", False)
        and state.get("run_commands", False)
    )
    hardware_targets = frozenset(tools.design_workspace_paths(state.get("run_root", "")).values())
    coding_session: dict[str, HardwareCodingToolset] = {}
    coding_factory = None
    toolset_kwargs: dict[str, Any] | None = None
    if coding_enabled and hardware_targets:
        if commands.agent_cfu_check_commands(state):
            check_index = 0

            def check_elaboration() -> dict[str, Any]:
                nonlocal check_index
                check_index += 1
                check_commands = commands.agent_cfu_check_commands(state, check_index=check_index)
                check_toolbox = stage_services._toolbox_for_stage(state, "implementation")
                results = [
                    effects.run_command(
                        state, check_toolbox, command,
                stage="implementation", rung="hw_check",
                        command_id="cfu_check_agent", timeout=1800, mutate=True)
                    for command in check_commands
                ]
                result = next(
                    (item for item in results if item.get("returncode") != 0),
                    results[-1],
                )
                rtl = (
                    Path(state.get("workdir", ".")).resolve()
                    / commands._agent_cfu_check_out_dir(state, check_index)
                    / "AgentCfu.v"
                )
                if result.get("returncode") == 0 and (not rtl.is_file() or rtl.stat().st_size == 0):
                    result = dict(result)
                    result["returncode"] = 1
                    result["stderr_tail"] = f"isolated elaboration produced no non-empty RTL at {rtl}"
                return result

            toolset_kwargs = {
                "allowed_targets": hardware_targets,
                "check_elaboration": check_elaboration,
                "diagnosis_required": bool(feedback),
            }

            def coding_factory(toolbox, **kwargs):
                toolset = HardwareCodingToolset(toolbox, **kwargs)
                coding_session["toolset"] = toolset
                return toolset
    user = prompts.hardware_prompt(
        state["task"],
        state.get("workload_spec", {}),
        state.get("workload_analysis", ""),
        state.get("design_contract", ""),
        _hardware_context(state, toolbox),
        profile=state.get("embench_profiles"),
        feedback=feedback,
        optimization=feedback_mod.optimization_directive(state),
        agent_tools=tools_enabled,
        tool_rounds=int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS),
        failure_ids=failure_ids,
        resolved_failure_ids=resolved_failure_ids,
        coding_tools=bool(toolset_kwargs),
        diagnosis_required=bool(feedback),
        artifact_paths=_hardware_evidence_paths(state),
    )
    fallback = fallbacks.deterministic_hardware_plan(state["task"], state.get("design_contract", ""))
    result, raw_output, tool_calls = llm_step._run_agent_step(
        state,
        toolbox,
        stage="implement",
        label="hardware",
        artifact_stage="implementation",
        tool_calls_relpath="09_implementation/hw_tool_calls.yaml",
        system=system,
        user=user,
        fallback=fallback,
        client=client,
        require_delivery=True,
        deliverable_hint=(
            "the EDIT_BEGIN/SEARCH/REPLACE, FILE_BEGIN/FILE_END, or "
            "PATCH_BEGIN/PATCH_END block required by the delivery protocol"
        ),
        failure_observations=failures,
        toolset_factory=coding_factory,
        toolset_kwargs=toolset_kwargs,
    )
    coding_toolset = coding_session.get("toolset")
    if coding_toolset and coding_toolset.touched_paths:
        apply_result = {
            "patch": tools.extract_patch(result.text),
            "summary": result.text + "\n\nHardware coding tools applied audited atomic edits; final delivery was not replayed.",
            "errors": [],
            "applied": True,
            "files": list(coding_toolset.touched_paths),
            "apply_result": {"returncode": 0, "parsed": {"touched_paths": list(coding_toolset.touched_paths)}},
            "gate_ok": True,
            "proposed": True,
        }
        if not any(token in result.text for token in ("EDIT_BEGIN", "FILE_BEGIN", "PATCH_BEGIN")):
            apply_result["errors"].append("tool edits require a final auditable EDIT/FILE/PATCH delivery")
            apply_result["gate_ok"] = False
        if feedback and not coding_toolset.session.diagnosis:
            apply_result["errors"].append("structured repair diagnosis was not accepted before editing")
            apply_result["gate_ok"] = False
    else:
        apply_result = delivery._apply_agent_output(
            state,
            result.text,
            toolbox=toolbox,
            attempts=state.get("hw_attempts"), domain="hardware",
            # The repair contract is enforced, not just prompted: a repair answer
            # without a REPAIR_DIAGNOSIS is rejected before anything is applied.
            require_diagnosis=(
                bool(feedback)
                and bool(getattr(result, "used_llm", False))
                and not bool(coding_toolset and coding_toolset.session.diagnosis)
            ),
        )
    intent_error = feedback_mod.tool_intent_error(result.text, str(getattr(result, "degraded_reason", "") or ""))
    if intent_error and not apply_result["applied"]:
        apply_result["errors"].append(intent_error)
        apply_result["summary"] += "\n\n" + intent_error
    accepted = bool(apply_result["gate_ok"] and not apply_result["errors"])
    if coding_toolset:
        if accepted:
            coding_toolset.session.commit()
        else:
            coding_toolset.session.rollback()
            apply_result["applied"] = False
            apply_result["files"] = []
            apply_result["gate_ok"] = False
    candidate_hash = intrinsics._hardware_candidate_hash(state, toolbox) if accepted else ""
    stage_services._write_hardware_artifact(state, result.text, apply_result, feedback)
    attempt = {
        "response_hash": parsing._attempt_digest(result.text),
        "error_hash": parsing._attempt_digest("\n".join(apply_result["errors"])),
        "search_key": feedback_mod.delivery_search_key(result.text),
        "applied": bool(apply_result["applied"]),
        # Human-readable excerpt for the prior-attempt ledger in repair prompts.
        "error_text": "; ".join(apply_result["errors"])[:300],
    }
    return {
        "hardware_plan": result.text,
        "hardware_patch": apply_result["patch"],
        "implementation_hw_summary": apply_result["summary"],
        "changed_design_files": apply_result["files"],
        "llm_raw_outputs": [raw_output],
        "tool_calls": [llm_step._tool_call_summary(call) for call in tool_calls],
        "hw_attempts": [attempt],
        "stage_jobs": "validation",
        "errors": apply_result["errors"],
        "gates": outcome.gates(state, {"implementation_hw": {
            "ok": apply_result["gate_ok"],
            "patch": bool(apply_result["patch"]),
            "applied": apply_result["applied"],
            "files": apply_result["files"],
            "repair": bool(feedback),
            "candidate_hash": candidate_hash,
            "tool_calls": len(tool_calls),
            "tools_degraded": str(getattr(result, "degraded_reason", "") or ""),
            "repair_diagnosis": (
                coding_toolset.session.diagnosis if coding_toolset and feedback
                else (("REPAIR_DIAGNOSIS" in result.text) if feedback else None)
            ),
            "response_hash": attempt["response_hash"],
            "error_hash": attempt["error_hash"],
            "errors": apply_result["errors"],
        }}),
        "iteration_history": state_mod.append_history(
            state, "Completed the hardware rung (AgentCfu.scala/AgentCfuFiber.scala)."
        ),
    }
